import{_ as t,o as r,c as a,a3 as d}from"./chunks/framework.B7pF4b99.js";const b=JSON.parse('{"title":"全站圖像教學研究與設計對照","description":"","frontmatter":{},"headers":[],"relativePath":"redesign.md","filePath":"redesign.md","lastUpdated":1794203475000}'),o={name:"redesign.md"};function s(n,e,i,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="全站圖像教學研究與設計對照" tabindex="-1">全站圖像教學研究與設計對照 <a class="header-anchor" href="#全站圖像教學研究與設計對照" aria-label="Permalink to &quot;全站圖像教學研究與設計對照&quot;">​</a></h1><p>研究日期：2026-11-08。此頁記錄改版前的教材研究、借鑑方式及與 WUWAOS 的差異；圖解由本專案重新繪製，不把其他 OS 的結構或執行結果當成本專案實作。</p><h2 id="研究方法與來源" tabindex="-1">研究方法與來源 <a class="header-anchor" href="#研究方法與來源" aria-label="Permalink to &quot;研究方法與來源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>來源</th><th>已檢視內容與圖像結構</th><th>採用方式</th></tr></thead><tbody><tr><td><a href="https://mit-pdos.github.io/xv6-riscv-book/" target="_blank" rel="noreferrer">MIT xv6 RISC-V Book</a></td><td>Organization、Page tables、Traps、Scheduling、File system、Logging。記憶體圖由位址欄位、表項、下一層表逐級連接；trap 與 context 圖分開硬體／核心路徑。</td><td>借鑑分層、位址標記和保存／還原的視覺關係；不複製 trampoline、核心佈局或多核心鎖設計。</td></tr><tr><td><a href="https://research.cs.wisc.edu/wind/OSTEP/" target="_blank" rel="noreferrer">OSTEP</a></td><td><a href="https://research.cs.wisc.edu/wind/OSTEP/cpu-sched.pdf" target="_blank" rel="noreferrer">Scheduling §7.7</a>、<a href="https://research.cs.wisc.edu/wind/OSTEP/vm-smalltables.pdf" target="_blank" rel="noreferrer">Advanced Page Tables</a>、<a href="https://research.cs.wisc.edu/wind/OSTEP/file-journaling.pdf" target="_blank" rel="noreferrer">FSCK/Journaling</a>。由簡化工作負載推演，再加入限制。</td><td>先列示例假設，再逐步說明；以時間軸對照 ready queue，持久化則明確區分 log 與 home。連到原教材，不在本站重製整章。</td></tr><tr><td><a href="https://operating-system-in-1000-lines.vercel.app/tw/" target="_blank" rel="noreferrer">OS in 1,000 Lines</a></td><td>從 boot 到 syscall／VirtIO／FS 的循序章節；<a href="https://operating-system-in-1000-lines.vercel.app/tw/11-page-table" target="_blank" rel="noreferrer">Page Table</a> 連接觀念、程式與觀察。</td><td>借鑑問題 → 最小流程 → 原始碼的順序。該教材的 RV32／Sv32 範例不能套用到本站 RV64／Sv39。</td></tr><tr><td><a href="https://srg-ics-uplb.github.io/cmsc125/viztools/index.html" target="_blank" rel="noreferrer">OSTEP VizTools</a></td><td><a href="https://srg-ics-uplb.github.io/cmsc125/viztools/scheduling/" target="_blank" rel="noreferrer">Scheduling</a> 與索引中的 trap、paging、swapping 示範，以決策步驟串接事件敘述。</td><td>每一步同時更新圖、狀態和敘述；不複製示範程式或把它的演算法清單當成 WUWAOS 功能。</td></tr><tr><td><a href="https://oslab.xikai.me/" target="_blank" rel="noreferrer">OS Lab</a></td><td><a href="https://oslab.xikai.me/cpu-scheduling" target="_blank" rel="noreferrer">CPU Scheduling</a> 的控制區、參數、就緒佇列、Gantt、事件與指標；已用瀏覽器檢視其行動版排列。</td><td>只保留幫助理解的輸入與視圖；WUWAOS 單核心 RR，不提供該站的多核心、MLFQ 或一般配置策略。</td></tr><tr><td><a href="https://www.os-book.com/OS10/slide-dir/index.html" target="_blank" rel="noreferrer">Operating System Concepts 10e</a></td><td>官方章節投影片入口與專案 <code>notes/</code> 對應課程內容。</td><td>狀態圖、分頁與 I/O 概念以筆記對照；官方投影片使用條款不等於一般公開網站轉載授權，因此不直接搬圖。</td></tr><tr><td><a href="https://shop.elsevier.com/books/book-companion/9780128203316" target="_blank" rel="noreferrer">Computer Organization and Design RISC-V Edition</a></td><td>官方 companion 與書目入口；CPU／記憶體位址與軟硬體界面以本專案筆記及 source 交叉對照。</td><td>借鑑將指令、暫存器、位址欄位分開說明的教學方向；沒有取得並重製該書內頁圖片，也不宣稱已讀取全部受限教材。</td></tr></tbody></table><h2 id="十二章的圖解研究對照" tabindex="-1">十二章的圖解研究對照 <a class="header-anchor" href="#十二章的圖解研究對照" aria-label="Permalink to &quot;十二章的圖解研究對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章節</th><th>原創視覺方案</th><th>參考案例／圖像結構</th><th>WUWAOS 差異與 source</th></tr></thead><tbody><tr><td>Getting Started</td><td>A：分層系統地圖；B：學習路線</td><td><a href="https://mit-pdos.github.io/xv6-riscv-book/first.html" target="_blank" rel="noreferrer">xv6 organization</a> 的核心職責分區；<a href="https://operating-system-in-1000-lines.vercel.app/tw/" target="_blank" rel="noreferrer">1,000 Lines 目錄</a> 的依賴順序。</td><td>單一靜態連結 S-mode kernel，UI 也在 S-mode；以 <code>kernel/boot/main.c</code> 與實際目錄分區。</td></tr><tr><td>Boot</td><td>B：QEMU → OpenSBI → 磁碟載入器或直接交接 → 核心 → 行程</td><td><a href="https://operating-system-in-1000-lines.vercel.app/tw/04-boot" target="_blank" rel="noreferrer">1,000 Lines Boot</a> 的分步啟動敘述。</td><td><code>run-disk</code> 由 <code>bootloader/boot.c</code> 讀取 WUFS <code>/boot/kernel.elf</code>。<code>run</code> 與 GUI 由 QEMU <code>-kernel</code> 載入。兩條路徑共用 <code>arch/riscv/entry.S</code> 與 <code>kernel/boot/main.c</code>。</td></tr><tr><td>Traps</td><td>B：U/S mode 泳道與 TrapFrame</td><td><a href="https://mit-pdos.github.io/xv6-riscv-book/trap.html" target="_blank" rel="noreferrer">xv6 trap fig. 4.1</a> 的進入／返回路徑。</td><td>使用 <code>trap_entry</code>／<code>trap_handler</code> 與共享核心映射；不畫 xv6 trampoline/uservec。ecall 的 sepc+4 與 page fault retry 分開。</td></tr><tr><td>Processes</td><td>A/B：PCB、state graph、雙 stack context switch</td><td><a href="https://mit-pdos.github.io/xv6-riscv-book/first.html" target="_blank" rel="noreferrer">xv6 process layout</a>、<a href="https://mit-pdos.github.io/xv6-riscv-book/sched.html" target="_blank" rel="noreferrer">context switch fig. 8.2</a>。</td><td>固定 16 PCB；KernelContext 與 TrapFrame 分工；共用 scheduler stack，無 SMP p-&gt;lock。<code>process.c</code>、<code>context.h</code>、<code>swtch.S</code>。</td></tr><tr><td>Scheduling</td><td>C/D：ready queue、Gantt、目前執行者</td><td><a href="https://research.cs.wisc.edu/wind/OSTEP/cpu-sched.pdf" target="_blank" rel="noreferrer">OSTEP RR figs. 7.6–7.7</a>、<a href="https://srg-ics-uplb.github.io/cmsc125/viztools/scheduling/" target="_blank" rel="noreferrer">VizTools scheduling</a>、<a href="https://oslab.xikai.me/cpu-scheduling" target="_blank" rel="noreferrer">OS Lab</a>。</td><td>kernel 固定 50 ms；網站可調 quantum 只是教學比較，沒有改 OS。核心不被 timer 搶占，wait/yield 可合作切換。</td></tr><tr><td>Memory</td><td>A/B/D：VA bit layout、三級表、PTE 與 frame</td><td><a href="https://mit-pdos.github.io/xv6-riscv-book/mem.html" target="_blank" rel="noreferrer">xv6 page tables figs. 3.1–3.4</a>、<a href="https://research.cs.wisc.edu/wind/OSTEP/vm-smalltables.pdf" target="_blank" rel="noreferrer">OSTEP page tables</a>。</td><td>9/9/9/12 bits，4 KiB leaf only。WUWAOS user VA 小於 2^38；不用 xv6 trampoline 地址、超頁或任意硬體 TLB 模擬。</td></tr><tr><td>Paging</td><td>C：PTE → RAM → swap slot，分成功／rollback</td><td><a href="https://research.cs.wisc.edu/wind/OSTEP/vm-beyondphys.pdf" target="_blank" rel="noreferrer">OSTEP swapping</a>、本專案 <code>notes/ch10 Virtual Momory.md</code>。</td><td>FIFO arrival、pins、VM Gate、先 revoke 再 swap；失敗 restore RAM，外層 fault 才 leave Gate。</td></tr><tr><td>I/O</td><td>A/C：VirtIO descriptor、avail／used、bounce 與 caller</td><td><a href="https://operating-system-in-1000-lines.vercel.app/tw/14-virtio" target="_blank" rel="noreferrer">1,000 Lines VirtIO</a>、<code>notes/ch12 I_O Systems.md</code> DMA 段落。</td><td>Block completion 為 scheduler poll；512-byte buffer／16-byte alignment；不是 IRQ 完成或直接 user-buffer DMA。</td></tr><tr><td>File System</td><td>A/C：directory → inode → blocks，log 與 home</td><td><a href="https://mit-pdos.github.io/xv6-riscv-book/fs.html" target="_blank" rel="noreferrer">xv6 FS figs. 10.1–10.3</a>、<a href="https://research.cs.wisc.edu/wind/OSTEP/file-journaling.pdf" target="_blank" rel="noreferrer">OSTEP journaling</a>。</td><td>WUFS 80-byte inode、8 direct + 8 indirect、512-byte sector、full-sector bounded redo；不畫 xv6 buffer cache 或 1 KiB block。</td></tr><tr><td>Applications</td><td>B：Shell → FD/OFD → TTY／pipe／file → syscall</td><td><a href="https://mit-pdos.github.io/xv6-riscv-book/unix.html" target="_blank" rel="noreferrer">xv6 interfaces</a>、<a href="https://operating-system-in-1000-lines.vercel.app/tw/13-system-call" target="_blank" rel="noreferrer">1,000 Lines syscall</a>。</td><td>自訂 ABI；GUI 是同一 user shell image；fan safe replace、受限 ELF，沒有 Linux API／argv 相容性。</td></tr><tr><td>Monitoring</td><td>A/B：snapshot → 累積 ticks 差 → CPU／RSS／Swap</td><td><a href="https://research.cs.wisc.edu/wind/OSTEP/cpu-sched.pdf" target="_blank" rel="noreferrer">OSTEP scheduling metrics</a>、<code>notes/ch5 CPU schedueling.md</code>。</td><td>CPU 為派發期間時間，含該行程 kernel work；不是硬體 utilization、load average 或純 CPU burst。<code>workstate.c</code>。</td></tr><tr><td>Writing</td><td>A/B：source → chapter／Vue → VitePress → gh-pages</td><td><a href="https://operating-system-in-1000-lines.vercel.app/tw/" target="_blank" rel="noreferrer">1,000 Lines 圖文／source 組織</a>、本 repository 發布工具。</td><td>repo 是唯一來源；無網站編輯後端；教學模型與 OS 驗收分開，歷史 spec 保留。</td></tr></tbody></table><h2 id="可追溯性與資產政策" tabindex="-1">可追溯性與資產政策 <a class="header-anchor" href="#可追溯性與資產政策" aria-label="Permalink to &quot;可追溯性與資產政策&quot;">​</a></h2><p>所有圖以 Vue/SVG/CSS 重新繪製，來源僅作概念與圖像結構參考。課程筆記可依使用者授權引用敘述，但其中第三方圖片仍需獨立確認授權。靜態向量圖由 source 管理，文字可搜尋／放大；沒有搬運教材截圖、未授權圖像或將外部模擬器嵌入本站。</p><p>一般教材概念、WUWAOS source 行為、網站的簡化假設各自標示。網站互動驗證與 OS runtime 驗證分開記錄，參見<a href="https://github.com/johnson931128/WUWAOS/blob/main/plan.md" target="_blank" rel="noreferrer">詳細計畫</a>。</p>',9)])])}const g=t(o,[["render",s]]);export{b as __pageData,g as default};
